// Unified icon system (Lucide geometry, consistent stroke) shared by every workspace.
const Icons = ShellIcons;

// Tooltip Flotante Educativo Desacoplado de Overflows mediante ReactDOM.createPortal
const InfoTip = ({ text, title }) => {
    const [coords, setCoords] = useState(null);
    const btnRef = useRef(null);

    const handleEnter = () => {
        if (!btnRef.current) return;
        const rect = btnRef.current.getBoundingClientRect();
        setCoords({
            top: rect.top + rect.height / 2,
            right: window.innerWidth - rect.left + 12
        });
    };

    const handleLeave = () => setCoords(null);

    return (
        <span className="inline-flex items-center ml-1.5 align-middle">
            <button 
                ref={btnRef}
                type="button"
                onMouseEnter={handleEnter}
                onMouseLeave={handleLeave}
                onClick={(e) => { e.stopPropagation(); coords ? handleLeave() : handleEnter(); }}
                className="w-3.5 h-3.5 rounded-full bg-djzinc-800 hover:bg-djcyan-500 hover:text-black border border-djzinc-600 flex items-center justify-center text-[9px] font-mono font-bold text-gray-400 transition-colors cursor-help select-none shrink-0"
            >
                i
            </button>

            {coords && ReactDOM.createPortal(
                <div 
                    style={{ 
                        position: 'fixed', 
                        top: `${coords.top}px`, 
                        right: `${coords.right}px`, 
                        transform: 'translateY(-50%)',
                        zIndex: 999999
                    }}
                    className="w-72 bg-djzinc-900 border border-djzinc-700 rounded-lg p-3 text-xs text-gray-200 shadow-[0_12px_36px_rgba(0,0,0,0.95),0_0_15px_rgba(6,182,212,0.2)] pointer-events-none select-none"
                >
                    <div className="absolute top-1/2 -right-1 -translate-y-1/2 w-2 h-2 bg-djzinc-900 border-t border-r border-djzinc-700 rotate-45"></div>

                    {title && (
                        <div className="text-[11px] font-bold text-djcyan-400 mb-1 uppercase tracking-wider flex items-center gap-1.5 border-b border-djzinc-800 pb-1">
                            <span className="w-1.5 h-1.5 rounded-full bg-djcyan-400"></span>
                            {title}
                        </div>
                    )}
                    <div className="text-[11px] leading-relaxed text-gray-300 font-sans break-words whitespace-normal">
                        {text}
                    </div>
                </div>,
                document.body
            )}
        </span>
    );
};

// Hash robusto determinista FNV-1a para huella única de cada pista
function getTrackHash(track) {
    if (!track) return 1337;
    const str = `${track.id || ''}|${track.title || track.t || ''}|${track.artist || track.a || ''}|${track.bpm || track.b || ''}|${track.key || track.k || ''}|${track.f || track.path || ''}`;
    let h = 2166136261;
    for (let i = 0; i < str.length; i++) {
        h ^= str.charCodeAt(i);
        h = Math.imul(h, 16777619);
    }
    return Math.abs(h >>> 0) || 1;
}

// Función auxiliar para calcular la envolvente estructural profesional por componentes DJ:
// - Genera arquetipos de estructura diferenciados (Club Extended, Radio Edit, Festival Climax, Melodic, Beat Tool)
// - Modula densidad rítmica según BPM, alturas y contrastes según Energía, y proporciones según Rol Acústico
// - Asegura huella visual y silueta única y reconocible para cada tema musical
function computeTrackStructuralBands(xNorm, seed, track = null) {
    const trackSeed = track ? getTrackHash(track) : (seed || 1);
    
    // Arquetipo estructural (0 a 4) según la semilla única de cada canción
    const archetype = trackSeed % 5;
    
    // Variación determinista de puntos estructurales
    const s1 = ((trackSeed % 23) - 11) * 0.007; // [-0.077, +0.077]
    const s2 = (((trackSeed >> 3) % 19) - 9) * 0.006;
    
    let b1Start, b1End, drop1End, b2Start, b2End, drop2End;
    
    if (archetype === 0) {
        // Extended Club Mix: Intro larga, primer drop potente, parón central prolongado, re-kick brutal
        b1Start = Math.max(0.18, 0.25 + s1);
        b1End = b1Start + 0.12 + Math.abs(s2);
        drop1End = Math.min(0.68, b1End + 0.22);
        b2Start = drop1End + 0.04;
        b2End = Math.min(0.84, b2Start + 0.10);
        drop2End = 0.90;
    } else if (archetype === 1) {
        // Radio / Vocal Edit: Intro corta, drop / estribillo muy temprano, puente vocal
        b1Start = Math.max(0.08, 0.14 + s1);
        b1End = b1Start + 0.08;
        drop1End = Math.min(0.50, b1End + 0.20);
        b2Start = drop1End + 0.05;
        b2End = Math.min(0.72, b2Start + 0.12);
        drop2End = 0.86;
    } else if (archetype === 2) {
        // Peak-Time Festival Banger: Build rápido, drop colosal y sostenido, mini break, segundo drop masivo
        b1Start = Math.max(0.14, 0.18 + s1);
        b1End = b1Start + 0.10;
        drop1End = Math.min(0.58, b1End + 0.26);
        b2Start = drop1End + 0.03;
        b2End = Math.min(0.76, b2Start + 0.08);
        drop2End = 0.92;
    } else if (archetype === 3) {
        // Progressive / Melodic: Construcción suave, gran breakdown melódico central, clímax tardío
        b1Start = Math.max(0.22, 0.30 + s1);
        b1End = b1Start + 0.16 + Math.abs(s2);
        drop1End = Math.min(0.78, b1End + 0.24);
        b2Start = 0.99; // 1 solo gran break
        b2End = 0.99;
        drop2End = 0.99;
    } else {
        // Underground Groove / Tool: Varios micro-cortes y drops constantes
        b1Start = Math.max(0.12, 0.16 + s1);
        b1End = b1Start + 0.07;
        drop1End = Math.min(0.48, b1End + 0.18);
        b2Start = drop1End + 0.08;
        b2End = Math.min(0.78, b2Start + 0.09);
        drop2End = 0.88;
    }

    // Parámetros acústicos específicos de la pista
    const durMs = track ? parseDurationMs(track.duration || "05:00") : 300000;
    const curMs = xNorm * durMs;
    const trimMs = (track && track.trim_start_ms) ? parseFloat(track.trim_start_ms) : 0;
    const downbeatMs = (track && track.first_downbeat_ms) ? parseFloat(track.first_downbeat_ms) : 0;

    // Si la posición analizada pertenece a la zona de silencio previa al recorte:
    if (trimMs > 0 && curMs < trimMs) {
        return { bass: 0.005, drums: 0.005, vocals: 0.005, treble: 0.005, isBreak: false, isSilence: true };
    }

    const bpm = track ? (parseFloat(track.bpm || track.b) || 124) : 124;
    const beatMs = 60000.0 / Math.max(30.0, bpm);
    
    // Fase rítmica armónica anclada al Downbeat 1.0.0
    // En curMs = downbeatMs, beatPhase = 0 -> cos(PI * 0) = 1.0 (golpe exacto de bombo coincidente con la línea de beatgrid)
    const beatPhase = (curMs - downbeatMs) / beatMs;
    
    const rawEnergy = track ? (track.energy !== undefined ? parseFloat(track.energy) : (track.e !== undefined ? parseFloat(track.e) : 0.65)) : 0.65;
    const energy = Math.max(0.35, Math.min(1.0, rawEnergy <= 1.0 ? rawEnergy : rawEnergy / 10));
    
    const role = String(track?.acoustic_role || track?.role || track?.genre || '').toLowerCase();
    const isBassDriver = role.includes('bass') || role.includes('sub') || role.includes('techno') || role.includes('tech');
    const isVocalLead = role.includes('vocal') || role.includes('lead') || role.includes('melodic') || role.includes('anthem');
    const isPercussive = role.includes('drum') || role.includes('perc') || role.includes('tool') || role.includes('groove');

    // Micro-modulaciones armónicas deterministas por pista
    const f1 = 18 + (trackSeed % 29);
    const f2 = 37 + ((trackSeed >> 3) % 41);
    const f3 = 73 + ((trackSeed >> 6) % 53);
    const microRipple = 0.85 + 0.15 * Math.sin(xNorm * f1) * Math.cos(xNorm * f2);
    const transientSpike = Math.pow(Math.abs(Math.sin(xNorm * f3)), 12);

    // Patrón rítmico sincrónico milimétrico con el Beatgrid:
    // Bombo en cada negra (beatPhase = 0, 1, 2, 3...)
    const beatGridKick = Math.pow(Math.abs(Math.cos(Math.PI * beatPhase)), 10);
    // Caja en tiempos 2 y 4 (beatPhase = 1, 3, 5...)
    const snareHit = Math.pow(Math.abs(Math.cos(Math.PI * (beatPhase - 1) * 0.5)), 8);
    // Hi-hats en contratiempos (offbeats beatPhase = 0.5, 1.5, 2.5...)
    const hatPattern = 0.35 + 0.65 * Math.pow(Math.abs(Math.sin(Math.PI * beatPhase)), 4);

    let bass = 0.15, drums = 0.15, vocals = 0.15, treble = 0.15;
    let isBreak = false;

    if (xNorm < b1Start) {
        // INTRO: Bombo limpio, hi-hats entrando, vocales lejanas
        const p = xNorm / b1Start;
        bass = (0.55 + 0.35 * beatGridKick) * (isBassDriver ? 1.3 : 1.0);
        drums = (0.45 + 0.40 * snareHit) * Math.min(1, p * 1.6);
        vocals = (0.15 + 0.25 * p) * (isVocalLead ? 1.4 : 0.8);
        treble = (0.30 + 0.50 * p) * hatPattern;
    } else if (xNorm >= b1Start && xNorm < b1End) {
        // BREAK 1 (PARÓN): Subida de sintetizadores, vocales prominentes
        isBreak = true;
        const p = (xNorm - b1Start) / (b1End - b1Start);
        bass = 0.03 + 0.03 * Math.sin(xNorm * 15);
        drums = (0.08 + 0.45 * Math.pow(p, 2.2) * snareHit);
        vocals = (0.80 + 0.20 * Math.sin(p * Math.PI)) * (isVocalLead ? 1.3 : 1.0);
        treble = 0.35 + 0.60 * Math.pow(p, 1.6);
    } else if (xNorm >= b1End && xNorm < drop1End) {
        // DROP 1 (CLÍMAX): Pegada atronadora en graves, caja con impacto
        bass = (0.88 + 0.12 * beatGridKick) * (isBassDriver ? 1.15 : 1.0) * energy;
        drums = (0.84 + 0.16 * snareHit) * (isPercussive ? 1.2 : 1.0) * energy;
        vocals = (0.60 + 0.30 * Math.sin(xNorm * 35)) * (isVocalLead ? 1.1 : 0.8);
        treble = (0.75 + 0.25 * hatPattern) * energy;
    } else if (xNorm >= b2Start && xNorm < b2End) {
        // BREAK 2 (PUENTE VOCAL / PARÓN CENTRAL)
        isBreak = true;
        const p = (xNorm - b2Start) / (b2End - b2Start);
        bass = 0.02 + 0.03 * Math.cos(xNorm * 10);
        drums = 0.06 + 0.50 * Math.pow(p, 2.5) * snareHit;
        vocals = (0.92 + 0.08 * Math.sin(p * Math.PI)) * (isVocalLead ? 1.25 : 1.0);
        treble = 0.40 + 0.55 * p;
    } else if (xNorm >= b2End && xNorm < drop2End) {
        // DROP 2 (RE-KICK MÁXIMO)
        bass = (0.95 + 0.05 * beatGridKick) * (isBassDriver ? 1.2 : 1.0) * energy;
        drums = (0.90 + 0.10 * snareHit) * (isPercussive ? 1.2 : 1.0) * energy;
        vocals = (0.65 + 0.25 * Math.sin(xNorm * 45)) * (isVocalLead ? 1.1 : 0.8);
        treble = (0.85 + 0.15 * hatPattern) * energy;
    } else {
        // OUTRO: Desvanecimiento progresivo para mezcla suave de salida en cabina
        const p = (xNorm - drop2End) / Math.max(0.01, 1 - drop2End);
        bass = Math.max(0.06, (0.70 - 0.55 * p) * (0.75 + 0.25 * beatGridKick));
        drums = Math.max(0.06, (0.50 - 0.42 * p));
        vocals = Math.max(0.04, (0.30 - 0.26 * p));
        treble = Math.max(0.04, (0.40 - 0.35 * p));
    }

    // Aplicar micro-modulación y energía
    bass = Math.min(1.0, bass * microRipple);
    drums = Math.min(1.0, drums * (0.9 + 0.2 * transientSpike));
    treble = Math.min(1.0, treble * (0.85 + 0.15 * microRipple));

    return { bass, drums, vocals, treble, isBreak, energy, archetype };
}

// Gestor de Ecualizador Web Audio API de 3 Bandas (BASS 250Hz, MID 1000Hz, HI 3500Hz)
function getAudioEQNodes(audioElement) {
    if (!audioElement) return null;
    if (window.__bwAudioNodes && window.__bwAudioNodes.audio === audioElement) {
        if (window.__bwAudioNodes.ctx.state === 'suspended') {
            window.__bwAudioNodes.ctx.resume().catch(() => {});
        }
        return window.__bwAudioNodes;
    }
    try {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (!AudioCtx) return null;
        const ctx = new AudioCtx();
        const source = ctx.createMediaElementSource(audioElement);
        
        const low = ctx.createBiquadFilter();
        low.type = 'lowshelf';
        low.frequency.value = 250;
        low.gain.value = 0;

        const mid = ctx.createBiquadFilter();
        mid.type = 'peaking';
        mid.frequency.value = 1000;
        mid.Q.value = 1.0;
        mid.gain.value = 0;

        const high = ctx.createBiquadFilter();
        high.type = 'highshelf';
        high.frequency.value = 3500;
        high.gain.value = 0;

        source.connect(low);
        low.connect(mid);
        mid.connect(high);
        high.connect(ctx.destination);

        const nodes = { audio: audioElement, ctx, source, low, mid, high };
        window.__bwAudioNodes = nodes;
        return nodes;
    } catch (e) {
        console.warn("Web Audio EQ initialization note:", e);
        return null;
    }
}

// Potenciómetro Rotatorio Hardware DJ de Alta Precisión
const RotaryKnob = ({ label, value = 0, min = -24, max = 6, defaultValue = 0, onChange, color = "#06b6d4" }) => {
    const normalized = Math.max(0, Math.min(1, (value - min) / (max - min)));
    const angle = -135 + normalized * 270;

    const handlePointerDown = (e) => {
        e.preventDefault();
        const startY = e.clientY || (e.touches && e.touches[0].clientY) || 0;
        const startVal = value;

        const onPointerMove = (me) => {
            const currentY = me.clientY || (me.touches && me.touches[0].clientY) || 0;
            const deltaY = startY - currentY;
            const range = max - min;
            const step = deltaY * (range / 120);
            const newVal = Math.min(max, Math.max(min, Math.round((startVal + step) * 10) / 10));
            if (onChange) onChange(newVal);
        };

        const onPointerUp = () => {
            window.removeEventListener('mousemove', onPointerMove);
            window.removeEventListener('mouseup', onPointerUp);
            window.removeEventListener('touchmove', onPointerMove);
            window.removeEventListener('touchend', onPointerUp);
        };

        window.addEventListener('mousemove', onPointerMove);
        window.addEventListener('mouseup', onPointerUp);
        window.addEventListener('touchmove', onPointerMove);
        window.addEventListener('touchend', onPointerUp);
    };

    return (
        <div className="flex flex-col items-center gap-1 select-none">
            <span className="text-[9px] font-mono font-bold text-gray-400 tracking-wider uppercase">{label}</span>
            <div 
                onMouseDown={handlePointerDown}
                onTouchStart={handlePointerDown}
                onDoubleClick={() => onChange && onChange(defaultValue)}
                className="w-10 h-10 rounded-full bg-gradient-to-b from-[#181826] to-[#0c0c14] border-2 border-djzinc-700 hover:border-gray-400 relative cursor-ns-resize shadow-[inset_0_2px_4px_rgba(0,0,0,0.8),0_2px_6px_rgba(0,0,0,0.6)] flex items-center justify-center group active:scale-95 transition-transform"
                title={`${label}: ${value > 0 ? '+' : ''}${value.toFixed(1)} dB (Doble clic para 0dB)`}
            >
                {/* Indicador de posición de rotación */}
                <div 
                    className="absolute w-full h-full rounded-full pointer-events-none"
                    style={{ transform: `rotate(${angle}deg)` }}
                >
                    <div 
                        className="w-1 h-3 rounded-full mx-auto mt-0.5 shadow-sm"
                        style={{ backgroundColor: color, boxShadow: `0 0 8px ${color}` }}
                    ></div>
                </div>
                {/* Tapa central estriada */}
                <div className="w-4 h-4 rounded-full bg-[#1e1e2c] border border-djzinc-600 pointer-events-none flex items-center justify-center shadow-inner">
                    <div className="w-1 h-1 rounded-full bg-djzinc-500"></div>
                </div>
            </div>
            <span className="text-[9px] font-mono text-gray-300 font-extrabold">
                {value > 0 ? `+${value.toFixed(1)}` : value.toFixed(1)} <span className="text-[7.5px] text-gray-500 font-normal">dB</span>
            </span>
        </div>
    );
};

// Mini visualizador armónico espectral interactivo en celda de tabla
// ─── PERF: TableHarmonicWaveform ─────────────────────────────────────────────
// 1. React.memo + comparación de props: solo re-renderiza si cambia la pista,
//    el estado play/pause, o el progreso supera un umbral del 2%.
// 2. OffscreenCanvas: las 4 bandas espectrales se precalculan UNA VEZ por pista
//    y se almacenan en bgBitmapRef. Cambiar de pista regenera el bitmap.
// 3. rAF para el playhead: el cursor se actualiza con requestAnimationFrame
//    leyendo progressRef (una ref, no estado) → sin renders de React.
// ─────────────────────────────────────────────────────────────────────────────
const TableHarmonicWaveform = React.memo(
  ({ track, duration = "05:00", onPlayTrack, isCurrentPlaying, onTogglePlay, playProgress = 0 }) => {
    const canvasRef   = useRef(null);
    const bgBitmapRef = useRef(null);   // bitmap precalculado de bandas espectrales
    const rafRef      = useRef(null);   // handle de requestAnimationFrame
    const progressRef = useRef(playProgress); // progreso leído por rAF sin setState
    const WIDTH = 112, HEIGHT = 28;

    const seed = getTrackHash(track);

    const handleClickScrub = (e) => {
        e.stopPropagation();
        if (isCurrentPlaying && onTogglePlay) { onTogglePlay(); return; }
        if (!canvasRef.current || !onPlayTrack) return;
        const rect = canvasRef.current.getBoundingClientRect();
        const pct  = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
        onPlayTrack(track, pct, true);
    };

    // ── Paso 1: Generar bitmap de fondo UNA VEZ por pista (Diseño Rayas BeatWave Logo) ─────
    useEffect(() => {
        let offscreen;
        try { offscreen = new OffscreenCanvas(WIDTH, HEIGHT); }
        catch (_) {
            offscreen = document.createElement('canvas');
            offscreen.width = WIDTH; offscreen.height = HEIGHT;
        }
        const ctx = offscreen.getContext('2d');
        const centerY = HEIGHT / 2;
        ctx.fillStyle = "#030408";
        ctx.fillRect(0, 0, WIDTH, HEIGHT);

        // Rayas corporativas con ancho reducido y paleta en la gama de azules y cian
        const barWidth = 1.2;
        const barStep = 2.0;

        for (let x = 0; x <= WIDTH - barWidth; x += barStep) {
            const xNorm = x / WIDTH;
            const { bass, drums, vocals, treble, isBreak } = computeTrackStructuralBands(xNorm, seed, track);
            
            // Altura de barra con amplio rango dinámico y contraste visual entre canciones
            const barEnergy = Math.min(1.0, (bass * 0.46 + drums * 0.32 + vocals * 0.20 + treble * 0.18) * 1.6);
            const h = Math.max(1.6, (HEIGHT * 0.45) * barEnergy);

            // Gradiente vertical corporativo: extremos azul cobalto, núcleo cian brillante
            const grad = ctx.createLinearGradient(0, centerY - h, 0, centerY + h);
            if (isBreak) {
                grad.addColorStop(0, "rgba(30, 58, 138, 0.40)");   // Azul cobalto tenue
                grad.addColorStop(0.5, "rgba(6, 182, 212, 0.70)");  // Cian tenue
                grad.addColorStop(1, "rgba(30, 58, 138, 0.40)");
            } else if (barEnergy > 0.75) {
                // Clímax / Drop: resplandor cian eléctrico con núcleo hielo
                grad.addColorStop(0, "rgba(37, 99, 235, 0.90)");    // Azul real
                grad.addColorStop(0.2, "rgba(14, 165, 233, 1.0)");   // Sky blue
                grad.addColorStop(0.5, "rgba(207, 250, 254, 1.0)");  // Cian blanco núcleo
                grad.addColorStop(0.8, "rgba(6, 182, 212, 1.0)");    // Cian puro
                grad.addColorStop(1, "rgba(37, 99, 235, 0.90)");
            } else {
                // Secciones rítmicas estándar
                grad.addColorStop(0, "rgba(30, 64, 175, 0.85)");    // Azul medio
                grad.addColorStop(0.3, "rgba(2, 132, 199, 0.95)");
                grad.addColorStop(0.5, "rgba(103, 232, 249, 0.95)"); // Cian luminoso
                grad.addColorStop(0.7, "rgba(2, 132, 199, 0.95)");
                grad.addColorStop(1, "rgba(30, 64, 175, 0.85)");
            }

            ctx.fillStyle = grad;
            ctx.beginPath();
            if (typeof ctx.roundRect === 'function') {
                ctx.roundRect(x, centerY - h, barWidth, h * 2, 0.6);
            } else {
                ctx.rect(x, centerY - h, barWidth, h * 2);
            }
            ctx.fill();
        }

        // Línea central tenue en cian corporativo
        ctx.strokeStyle = "rgba(6, 182, 212, 0.25)";
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(0, centerY);
        ctx.lineTo(WIDTH, centerY);
        ctx.stroke();

        // Convertir a ImageBitmap para renderizado GPU (fallback: canvas auxiliar)
        if (typeof offscreen.transferToImageBitmap === 'function') {
            bgBitmapRef.current = offscreen.transferToImageBitmap();
        } else {
            bgBitmapRef.current = offscreen;
        }
    }, [seed, track]); // seed y track estables por pista → recalcula al cambiar de pista o datos

    // ── Paso 2: Configurar canvas principal con DPR correcto ──────────────────
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const dpr = window.devicePixelRatio || 1;
        canvas.width  = WIDTH * dpr;
        canvas.height = HEIGHT * dpr;
        const ctx = canvas.getContext('2d');
        ctx.scale(dpr, dpr);
    }, []); // solo al montar

    // ── Paso 3: Bucle rAF para dibujar el playhead ────────────────────────────
    // No lee ningún estado React → cero re-renders durante la reproducción.
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const draw = () => {
            if (!bgBitmapRef.current) return;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(bgBitmapRef.current, 0, 0, WIDTH, HEIGHT);
            if (isCurrentPlaying) {
                const px = WIDTH * Math.min(1, Math.max(0, progressRef.current));
                ctx.strokeStyle = "#ffffff"; ctx.lineWidth = 1.5;
                ctx.beginPath(); ctx.moveTo(px, 0); ctx.lineTo(px, HEIGHT); ctx.stroke();
            }
        };
        if (isCurrentPlaying) {
            const loop = () => { draw(); rafRef.current = requestAnimationFrame(loop); };
            rafRef.current = requestAnimationFrame(loop);
        } else {
            draw();
            if (rafRef.current) { cancelAnimationFrame(rafRef.current); rafRef.current = null; }
        }
        return () => { if (rafRef.current) { cancelAnimationFrame(rafRef.current); rafRef.current = null; } };
    }, [isCurrentPlaying, seed]);

    // ── Paso 4: Sincronizar ref de progreso sin provocar renders ─────────────
    useEffect(() => { progressRef.current = playProgress; }, [playProgress]);

    return (
        <div onClick={handleClickScrub} className="w-28 h-7 bg-[#040407] rounded border border-djzinc-800 relative overflow-hidden group cursor-pointer hover:border-djcyan-400 transition-colors flex items-center justify-center">
            <canvas ref={canvasRef} style={{ width: "112px", height: "28px", display: "block" }} />
            <span className="absolute bottom-0.5 right-1 text-[8px] font-mono text-gray-400 opacity-60 group-hover:opacity-100">{duration}</span>
            {isCurrentPlaying && (
                <div className="absolute top-1 left-1 w-2 h-2 rounded-full bg-djcyan-400 animate-pulse"></div>
            )}
        </div>
    );
  },
  // ── Función de comparación (areEqual): evita re-renders innecesarios ────────
  (prev, next) => {
      if ((prev.track && prev.track.id) !== (next.track && next.track.id)) return false;
      if (prev.isCurrentPlaying !== next.isCurrentPlaying) return false;
      // Si está sonando, solo re-renderiza si el progreso cambia >2% (umbral visual)
      if (prev.isCurrentPlaying && Math.abs(prev.playProgress - next.playProgress) > 0.02) return false;
      if (prev.onPlayTrack !== next.onPlayTrack) return false;
      if (prev.onTogglePlay !== next.onTogglePlay) return false;
      if (prev.duration !== next.duration) return false;
      return true; // props equivalentes → saltar render
  }
);

