        {
            title: "Entorno & Visibilidad",
            icon: "🕶️",
            items: [
                { key: "L", desc: "Alternar Modo Cabina Oscura (High-Contrast Club Mode)" },
                { key: "? / H", desc: "Abrir o cerrar esta guía de atajos" },
                { key: "ESC", desc: "Cerrar cualquier ventana modal activa" },
            ]
        }
